// Inputs for generate.mts. Every expected value is recorded from the real TS
// baseline; this file only lists what to run.
//
// Step ops (one fresh BackgroundTaskRuntime + BackgroundSubagentRuntime per
// scenario, fixed clock, sessionId "s1" unless `session` is given):
//   tool:  { op: 'tool', tool, input, session?, abort?: 'pre' | <ms> }
//   validate: { op: 'validate', tool, input }
//   sync (not recorded beyond an assertion): awaitBytes { task, bytes },
//     awaitStatus { task, status }, touch { path }, groupGone { task }
//   lifecycle: dispose, sdkStop { sessionKey, task }, sdkList { sessionKey, task? }
//   subagents: subStart { kind?, sessionId, behavior }, subRelease { sub }, subTick
// "<task:N>" in an input is the N-th created task id; "<sub:N>" the N-th subagent.

const blockUntil = (file, before = '', after = '') =>
  `${before}until [ -f ${file} ]; do sleep 0.02; done; ${after}`;

